-- Migración aditiva 3.0: importar después del esquema y los datos demo.
DELIMITER $$
DROP PROCEDURE IF EXISTS migrar_v3$$
CREATE PROCEDURE migrar_v3()
BEGIN
 IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='clientes' AND column_name='activo') THEN
  ALTER TABLE clientes ADD COLUMN activo BOOLEAN NOT NULL DEFAULT TRUE;
 END IF;
 IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='servicios' AND column_name='activo') THEN
  ALTER TABLE servicios ADD COLUMN activo BOOLEAN NOT NULL DEFAULT TRUE;
 END IF;
END$$
CALL migrar_v3()$$
DROP PROCEDURE migrar_v3$$
DELIMITER ;
CREATE TABLE IF NOT EXISTS auditoria(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL,accion VARCHAR(60) NOT NULL,referencia VARCHAR(150) NOT NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id),INDEX ix_auditoria_fecha(fecha));
CREATE TABLE IF NOT EXISTS proveedores(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(150) NOT NULL UNIQUE,telefono VARCHAR(30) NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS productos(id BIGINT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(40) NOT NULL UNIQUE,nombre VARCHAR(150) NOT NULL,categoria VARCHAR(80) NOT NULL,precio DECIMAL(12,2) NOT NULL CHECK(precio>0),minimo INT NOT NULL DEFAULT 3 CHECK(minimo>=0),activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS compras(id BIGINT AUTO_INCREMENT PRIMARY KEY,proveedor_id BIGINT NOT NULL,usuario_id BIGINT NOT NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,total DECIMAL(12,2) NOT NULL CHECK(total>0),FOREIGN KEY(proveedor_id) REFERENCES proveedores(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS lotes(id BIGINT AUTO_INCREMENT PRIMARY KEY,producto_id BIGINT NOT NULL,compra_id BIGINT NOT NULL,codigo VARCHAR(60) NOT NULL,vencimiento DATE NOT NULL,costo DECIMAL(12,2) NOT NULL CHECK(costo>0),cantidad INT NOT NULL CHECK(cantidad>=0),FOREIGN KEY(producto_id) REFERENCES productos(id),FOREIGN KEY(compra_id) REFERENCES compras(id),INDEX ix_lote_fefo(producto_id,vencimiento));
CREATE TABLE IF NOT EXISTS cajas(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL,apertura DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,cierre DATETIME NULL,fondo DECIMAL(12,2) NOT NULL CHECK(fondo>=0),esperado DECIMAL(12,2) NULL,contado DECIMAL(12,2) NULL,diferencia DECIMAL(12,2) NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id),INDEX ix_caja_abierta(usuario_id,cierre));
CREATE TABLE IF NOT EXISTS ventas(id BIGINT AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(50) NOT NULL UNIQUE,cliente_id BIGINT NOT NULL,caja_id BIGINT NOT NULL,usuario_id BIGINT NOT NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,subtotal DECIMAL(12,2) NOT NULL,descuento DECIMAL(12,2) NOT NULL,impuesto DECIMAL(12,2) NOT NULL,total DECIMAL(12,2) NOT NULL,metodo VARCHAR(20) NOT NULL CHECK(metodo IN ('EFECTIVO','TARJETA','TRANSFERENCIA')),recibido DECIMAL(12,2) NOT NULL,cambio DECIMAL(12,2) NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'EMITIDA' CHECK(estado IN ('EMITIDA','ANULADA')),motivo VARCHAR(255) NULL,FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(caja_id) REFERENCES cajas(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),INDEX ix_venta_fecha(fecha));
CREATE TABLE IF NOT EXISTS venta_detalles(id BIGINT AUTO_INCREMENT PRIMARY KEY,venta_id BIGINT NOT NULL,lote_id BIGINT NOT NULL,cantidad INT NOT NULL CHECK(cantidad>0),precio DECIMAL(12,2) NOT NULL CHECK(precio>0),FOREIGN KEY(venta_id) REFERENCES ventas(id),FOREIGN KEY(lote_id) REFERENCES lotes(id));
CREATE TABLE IF NOT EXISTS movimientos_caja(id BIGINT AUTO_INCREMENT PRIMARY KEY,caja_id BIGINT NOT NULL,usuario_id BIGINT NOT NULL,venta_id BIGINT NULL,cita_id BIGINT NULL,importe DECIMAL(12,2) NOT NULL,concepto VARCHAR(150) NOT NULL,metodo VARCHAR(20) NOT NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(caja_id) REFERENCES cajas(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(venta_id) REFERENCES ventas(id),FOREIGN KEY(cita_id) REFERENCES citas(id));
CREATE TABLE IF NOT EXISTS puntos(id BIGINT AUTO_INCREMENT PRIMARY KEY,cliente_id BIGINT NOT NULL,venta_id BIGINT NULL,cita_id BIGINT NULL,valor INT NOT NULL,concepto VARCHAR(150) NOT NULL,fecha DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY ux_puntos_venta(venta_id,concepto),UNIQUE KEY ux_puntos_cita(cita_id,concepto),FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(venta_id) REFERENCES ventas(id),FOREIGN KEY(cita_id) REFERENCES citas(id));
CREATE TABLE IF NOT EXISTS recordatorios(id BIGINT AUTO_INCREMENT PRIMARY KEY,cliente_id BIGINT NOT NULL,usuario_id BIGINT NOT NULL,titulo VARCHAR(150) NOT NULL,categoria VARCHAR(40) NOT NULL,prioridad VARCHAR(15) NOT NULL CHECK(prioridad IN ('ALTA','MEDIA','BAJA')),fecha DATETIME NOT NULL,repetir_dias INT NOT NULL DEFAULT 0 CHECK(repetir_dias BETWEEN 0 AND 365),estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE' CHECK(estado IN ('PENDIENTE','COMPLETADA','POSPUESTA')),FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),INDEX ix_recordatorio_fecha(fecha,estado));
CREATE TABLE IF NOT EXISTS reglas_puntos(id INT PRIMARY KEY,valor_compra DECIMAL(12,2) NOT NULL,umbral INT NOT NULL,bono DECIMAL(12,2) NOT NULL);
INSERT IGNORE INTO reglas_puntos VALUES(1,100,100,100);
